<?php require 'config/config.php';require_role(['accountant']);$page_title='Reports';$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$s=$pdo->prepare('SELECT COALESCE(SUM(total),0) n FROM sales WHERE DATE(created_at) BETWEEN ? AND ?');$s->execute([$from,$to]);$sales=$s->fetch()['n'];$s=$pdo->prepare('SELECT COALESCE(SUM(amount),0) n FROM expenses WHERE expense_date BETWEEN ? AND ?');$s->execute([$from,$to]);$expenses=$s->fetch()['n'];$s=$pdo->prepare('SELECT COUNT(*) n FROM sales WHERE DATE(created_at) BETWEEN ? AND ?');$s->execute([$from,$to]);$count=$s->fetch()['n'];require 'includes/header.php';?><h1>Business reports</h1><div class="panel"><form method="get" class="formgrid"><div><label>From</label><input type="date" name="from" value="<?=e($from)?>"></div><div><label>To</label><input type="date" name="to" value="<?=e($to)?>"></div><div style="align-self:end"><button>Generate report</button></div></form></div><div class="cards"><div class="card">Sales<div class="metric"><?=money($sales)?></div></div><div class="card">Expenses<div class="metric"><?=money($expenses)?></div></div><div class="card">Difference<div class="metric"><?=money($sales-$expenses)?></div></div><div class="card">Number of sales<div class="metric"><?=$count?></div></div></div><p class="muted">This is a management summary, not a complete statutory financial statement. Unpaid sales are included in recorded sales totals.</p><?php require 'includes/footer.php';?>